DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM "public"."strategy_definition_revisions" r
    WHERE r."definition_id" IN ('qc-asset-class-trend', 'qc-futures-trend-carry', 'qc-gold-fed-model', 'qc-iv-rank-gate', 'qc-momentum-rotation', 'qc-oil-predicts-equity', 'qc-opex-week', 'qc-regime-put-vrp', 'qc-same-month-seasonality', 'qc-turn-of-the-month', 'qc-vix-term-gate')
      AND (r."id" NOT IN ('qc-def-qc-asset-class-trend-r1', 'qc-def-qc-futures-trend-carry-r1', 'qc-def-qc-gold-fed-model-r1', 'qc-def-qc-iv-rank-gate-r1', 'qc-def-qc-momentum-rotation-r1', 'qc-def-qc-oil-predicts-equity-r1', 'qc-def-qc-opex-week-r1', 'qc-def-qc-regime-put-vrp-r1', 'qc-def-qc-same-month-seasonality-r1', 'qc-def-qc-turn-of-the-month-r1', 'qc-def-qc-vix-term-gate-r1') OR r."revision" <> 1 OR r."created_by" <> 'migration:0061')
  ) THEN
    RAISE EXCEPTION 'qc-port definitions have later revisions or rows by other authors; refusing rollback';
  END IF;
  IF EXISTS (
    SELECT 1 FROM "public"."strategies" s JOIN qc_port_links l ON l.id = s."id"
    WHERE s."params" <> '[]'::jsonb AND s."params" <> l.params
  ) THEN
    RAISE EXCEPTION 'qc-port library params were changed after 0061; refusing rollback';
  END IF;
  IF EXISTS (
    SELECT 1 FROM qc_port_links l
    WHERE EXISTS (SELECT 1 FROM "public"."strategy_presets" p WHERE p."strategy_id" = l.id)
      OR EXISTS (SELECT 1 FROM "public"."strategy_specs" q WHERE q."strategy_id" = l.id)
      OR EXISTS (SELECT 1 FROM "public"."backtest_results" b WHERE b."strategy_id" = l.id)
      OR EXISTS (SELECT 1 FROM "public"."backtest_runs" r WHERE r."strategy_id" = l.id)
      OR EXISTS (SELECT 1 FROM "public"."optimization_runs" o WHERE o."strategy_id" = l.id)
      OR EXISTS (SELECT 1 FROM "public"."deployment_requests" d WHERE d."strategy_id" = l.id)
      OR EXISTS (SELECT 1 FROM "public"."autopilot_candidates" a WHERE a."strategy_id" = l.id)
  ) THEN
    RAISE EXCEPTION 'qc-port seed strategies are referenced by runs, results or specs; refusing rollback';
  END IF;
END
$$;
UPDATE "public"."strategies" s SET "params" = '[]'::jsonb FROM qc_port_links l WHERE l.id = s."id" AND s."params" = l.params;
